import {skills,resources} from './model.mjs';
import {skillCoverage} from './discovery-model.mjs';
import {learningExercises} from './journey.mjs';
import {executionPanel,reflectionPanel} from './experience.mjs';
import {projectIntake,projectReport,workContextLabels} from './work-profile.mjs';
import {transitionStrategy} from './work-context.mjs';
import {repathLogo} from './branding.mjs';

const roleTasks={
  analyst:['梳理业务流程，用数据提出改进建议。','Study business processes and use evidence to recommend improvements.','Kaji proses perniagaan dan cadangkan penambahbaikan berasaskan data.'],
  project:['安排项目、协调资源，推动工作按计划交付。','Coordinate plans, resources and delivery across a project.','Selaras pelan, sumber dan pelaksanaan projek.'],
  market:['研究客户和市场，帮助团队做商业决策。','Study customers and markets to support business decisions.','Kaji pelanggan dan pasaran untuk menyokong keputusan.']
};
const plainChips=(c,ids,kind='')=>ids.map(id=>`<span class="d-skill ${kind}">${c.esc(c.skillName(id))}</span>`).join('');
const arrow=c=>c.icon('arrow');
function linkResource(c,skill){const r=['data','reporting','spreadsheet'].includes(skill)?resources.data:['planning','budgeting'].includes(skill)?resources.project:null;return r?`<a class="d-resource" href="${r.url}" target="_blank" rel="noopener noreferrer">${c.esc(r.provider)} ${c.icon('external')}</a>`:''}

export function discoveryHeader(c){const {state,t,icon}=c;const items=[['welcome','navDiscover'],['explore','navStrengths'],['opportunities','navDirections'],['pathway','navPlan']];return `<header class="d-header"><button class="d-brand" data-action="intro-home" aria-label="RePath 首页">${repathLogo({decorative:true})}</button><nav class="d-navigation" aria-label="${t('workspace')}">${items.map(([view,label])=>`<button ${view==='explore'?'data-action="my-experience"':`data-view="${view}"`} class="${state.view===view||view==='welcome'&&state.view==='sample'?'active':''}" ${state.view===view?'aria-current="page"':''}>${t(label)}</button>`).join('')}<button class="d-records-mobile" data-action="records" aria-label="${t('recordsTitle')}">${t('recordsShort')}</button></nav><div class="d-header-actions"><button class="d-records-entry" data-action="records" aria-label="${t('recordsTitle')}" title="${t('recordsTitle')}">${icon('archive')}<span>${t('recordsShort')}</span></button><button class="d-theme-toggle" data-action="toggle-theme" aria-label="${t(state.theme==='dark'?'themeToLight':'themeToDark')}" title="${t(state.theme==='dark'?'themeToLight':'themeToDark')}">${icon(state.theme==='dark'?'sun':'moon')}<span>${t(state.theme==='dark'?'themeLight':'themeDark')}</span></button><button class="d-plan-link" data-action="pricing">${state.pro?'Pro':t('navPricing')}</button><label class="d-language">${icon('globe')}<select id="language" aria-label="Language / 语言 / Bahasa"><option value="zh" ${state.lang==='zh'?'selected':''}>中文</option><option value="en" ${state.lang==='en'?'selected':''}>English</option><option value="ms" ${state.lang==='ms'?'selected':''}>Melayu</option></select></label><button class="d-login" data-action="auth-login">${t('loginShort')}</button><button class="d-menu" data-action="toggle-navigation" aria-label="Menu" aria-expanded="false">${icon('menu')}</button></div></header>`}

export function discoveryFooter(c){return `<footer class="d-footer"><span class="d-footer-brand">${repathLogo()}<small>Malaysia first.</small></span><div><button data-view="signals">${c.t('signals')}</button><button data-view="saved">${c.t('saved')}</button><button data-view="pricing">Free / Pro</button><span>${c.t('quietFooter')}</span></div></footer>`}

export function discoveryProgress(c){const step=c.state.view==='setup'?Math.min(1,c.state.setupStep):{sample:0,explore:0,opportunities:2,pathway:3}[c.state.view];if(step===undefined)return '';return `<div class="d-progress w-progress"><ol>${c.t('journeySteps').map((label,i)=>`<li class="${step===i?'active':step>i?'done':''}"><b>${step>i?c.icon('check'):i+1}</b><span>${c.esc(label)}</span></li>`).join('')}</ol><div class="w-progress-result"><small class="w-data-mode">${c.t(c.state.isSample?'sampleBadge':'personalBadge')}</small><div>${c.icon('arrow')}<span>${c.t('flowResult')}</span></div></div></div>`}

export function discoveryLanding(c){const {t,icon,button}=c;return `<main class="d-start-screen"><div class="d-start-stage"><section class="d-start-copy"><span class="d-start-label">${t('entryLabel')}</span><h1>${t('dHero1')}<span>${t('dHero2')}</span></h1><p>${t('dHeroDesc')}</p><div class="d-start-actions">${button(t('startMine'),'start-profile','primary-button','arrow')}${button(t('seeExample'),'show-sample','d-case-button','briefcase')}</div><small>${t('dHeroNote')}</small></section><section class="d-start-example" aria-label="${t('entryExample')}"><div class="d-example-top"><span>${t('entryExample')}</span><span class="d-example-tag">${t('entrySample')}</span></div><div class="d-example-route"><div><span class="d-example-icon">${icon('briefcase')}</span><strong>${t('caseExperience')}</strong></div><span class="d-example-arrow">${arrow(c)}</span><div><span class="d-example-icon next">${icon('chart')}</span><strong>${t('caseDirection')}</strong></div></div><div class="d-example-steps"><span>${icon('check')}${t('entryKeep')}</span><span>${icon('book')}${t('entryLearn')}</span></div><button class="d-entry-plan" data-action="pricing"><span><b>Free</b>${t('entryFree')}</span><span><b>Pro</b>${t('entryPro')}</span>${arrow(c)}</button></section></div><section class="d-entry-audiences" aria-label="${t('entryAudience')}">${[['entryTransition','transition','compass'],['entryEmployed','employed','up'],['entryReturning','returning','refresh']].map(([label,audience,mark])=>`<button data-action="show-sample" data-audience="${audience}"><span>${icon(mark)}${t(label)}</span>${arrow(c)}</button>`).join('')}</section></main>`}

export function sampleJourney(c){const {state,t,esc,local,icon,ranking,button}=c;const best=ranking()[0];return `<main class="d-page"><div class="d-page-heading"><span class="d-eyebrow">${t('sampleEyebrow')}</span><h1>${t('sampleTitle')}</h1><p>${t('sampleSub')}</p></div><div class="d-story-strip"><article><span class="d-eyebrow">01 / ${t('caseStart')}</span><div class="d-story-avatar">${icon('briefcase')}</div><h2>${esc(c.profileRole())}</h2><p>${state.profile.years} ${t('years')}</p><div class="d-inline-skills">${plainChips(c,state.profile.skills.slice(0,3))}</div></article><span class="d-story-arrow">${arrow(c)}</span><article class="d-story-middle"><span class="d-eyebrow">02 / ${t('caseCarry')}</span><strong class="d-count">${best.matched.length}<small> / ${best.required.length}</small></strong><p>${t('retained')}</p><div class="d-inline-skills">${plainChips(c,best.matched)}</div></article><span class="d-story-arrow">${arrow(c)}</span><article class="d-story-result"><span class="d-eyebrow">03 / ${t('caseNext')}</span><div class="d-story-avatar">${icon(best.icon)}</div><h2>${esc(local(best.title))}</h2><p>${esc(local(roleTasks[best.id]||best.description))}</p><span class="d-fit-label">${t('gapShort')}</span><div class="d-inline-skills">${best.missing.length?plainChips(c,best.missing,'new'):t('allCovered')}</div></article></div><div class="d-case-next"><span>${t('caseLearn')}</span><h3>${best.missing.length?esc(c.skillName(best.missing[0])):t('step3')}</h3><p>${best.missing.length?esc(local(learningExercises[best.missing[0]])):t('step3Desc')}</p></div><div class="d-page-actions">${button(t('replaceWithMine'),'start-profile','primary-button','arrow')}${button(t('otherPaths'),'open-directions','d-text-button','arrow')}<button class="d-subtle-button" data-action="next-sample">${t('changeSample')}${icon('refresh')}</button></div><p class="d-small-note">${t('exampleOnly')}</p></main>`}

export function profileIntake(c){return projectIntake(c)}

function radar(c){const groups=skillCoverage(c.state.profile.skills);const point=(i,r)=>[145+Math.cos(-Math.PI/2+i*Math.PI*2/groups.length)*r,131+Math.sin(-Math.PI/2+i*Math.PI*2/groups.length)*r];const polygon=r=>groups.map((_,i)=>point(i,r).join(',')).join(' ');return `<svg class="d-radar" viewBox="0 0 290 267" role="img" aria-label="${c.t('coverageNote')}">${[1,.75,.5,.25].map(r=>`<polygon points="${polygon(84*r)}" fill="none" stroke="#33435a" stroke-width="1"/>`).join('')}${groups.map((_,i)=>{const p=point(i,84);return `<line x1="145" y1="131" x2="${p[0]}" y2="${p[1]}" stroke="#2c3b51"/>`}).join('')}<polygon points="${groups.map((g,i)=>point(i,84*g.count/g.total).join(',')).join(' ')}" fill="#7895d32a" stroke="#90a9df" stroke-width="1.5"/>${groups.map((g,i)=>{const p=point(i,112);return `<text x="${p[0]}" y="${p[1]}" text-anchor="middle" fill="#a8b4ca" font-size="9">${c.esc(c.local(g.label))}</text>`}).join('')}</svg>`}

export function strengthReport(c){return projectReport(c,radar(c))}

export function directionList(c){const {t,state,local,esc,button,ranking,icon}=c;const strategy=transitionStrategy(state.profile);return `<main class="d-page"><div class="d-page-heading d-heading-row"><div><span class="d-eyebrow">${esc(c.profileRole())} → WHAT’S NEXT</span><h1>${t(state.view==='saved'?'saved':'directionsTitle')}</h1><p>${t('directionsSub')}</p></div>${button(t('editExperience'),'start-profile','small-button','edit')}</div><section class="w-strategy-summary"><strong>${esc(local(strategy.title))}</strong><p>${esc(local(strategy.description))}</p><small>${workContextLabels(c)}</small></section><div class="d-route-list">${!ranking().length?`<section class="empty-state"><h2>${t('emptySaved')}</h2><p>${t('emptySavedDesc')}</p>${button(t('backExplore'),'open-directions','primary-button','arrow')}</section>`:''}${ranking().map((role,index)=>`<article class="d-route-row"><span class="d-route-number">0${index+1}</span><div class="d-route-main"><span class="d-eyebrow">${t('adjacentMove')} · O*NET ${role.code}</span><h2>${esc(local(role.title))}</h2><p>${esc(local(roleTasks[role.id]||role.description))}</p><div class="d-route-skill-line"><span>${t('carryShort')}</span>${plainChips(c,role.matched.slice(0,3))}</div><div class="d-route-skill-line"><span>${t('gapShort')}</span>${role.missing.length?plainChips(c,role.missing,'new'):`<span class="d-skill">${t('allCovered')}</span>`}</div></div><div class="d-route-score"><button data-action="why" data-id="${role.id}" aria-label="${t('sourceDetails')} · ${esc(local(role.title))}"><strong>${role.score}<small>/100</small></strong><span>${t('fitShort')}${icon('info')}</span></button>${button(t('lookCloser'),'choose','primary-button','arrow',`data-id="${role.id}"`)}<button class="d-save-link" data-action="save" data-id="${role.id}" aria-pressed="${state.saved.includes(role.id)}">${icon('bookmark')}${t(state.saved.includes(role.id)?'unsave':'save')}</button></div></article>`).join('')}</div><p class="d-small-note">${t(state.profile.hoursConfirmed?'fitNote':'noLearningInput')}</p><details class="d-scenario" ${state.scenario==='fast'?'open':''}><summary>${t('scenario')}</summary><label class="scenario-switch">${t('scenario')}<select id="scenario" aria-label="${t('scenario')}"><option value="moderate" ${state.scenario==='moderate'?'selected':''}>${t('moderate')}</option><option value="fast" ${state.scenario==='fast'?'selected':''}>${t('fast')}</option></select></label><p>${t('scenarioNote')}</p></details></main>`}

export function selectedPath(c){const {t,state,targetRole,local,esc,icon,button}=c;const role=targetRole();const firstGap=role.missing[0];const ready=c.isPlanReady();const strategy=transitionStrategy(state.profile);return `<main class="d-page"><div class="d-page-heading d-heading-row"><div><span class="d-eyebrow">${t('chosenPath')} · ${esc(local(role.title))}</span><h1>${t(ready?'starterReady':'pathNextTitle')}</h1><p>${t(ready?'starterReadyDesc':'pathNextSub')}</p></div><button class="d-text-button" data-action="open-directions">${t('chooseDifferent')}${arrow(c)}</button></div><section class="w-strategy-summary"><strong>${esc(local(strategy.title))}</strong><ol>${local(strategy.actions).map(item=>`<li>${esc(item)}</li>`).join('')}</ol></section>${!ready?`<section class="d-target-brief"><div class="d-target-title"><span>${icon(role.icon)}</span><div><h2>${esc(local(role.title))}</h2><p>${esc(local(roleTasks[role.id]||role.description))}</p></div></div><div class="d-target-columns"><div><span class="d-eyebrow">${t('carryShort')}</span><div class="d-inline-skills">${plainChips(c,role.matched)}</div></div><div><span class="d-eyebrow">${t('learnThis')}</span><div class="d-inline-skills">${role.missing.length?plainChips(c,role.missing,'new'):t('allCovered')}</div></div></div><div class="d-first-exercise"><span class="d-eyebrow">${t(strategy.id==='income'?'parallelPractice':'firstPractice')}</span><h3>${firstGap?esc(c.skillName(firstGap)):t('step3')}</h3><p>${firstGap?esc(local(learningExercises[firstGap])):t('step3Desc')}</p>${firstGap?linkResource(c,firstGap):''}</div></section><section class="d-time-choice"><div><span class="d-eyebrow">${t('onlyNowTime')}</span><h2>${t('timeQuestion')}</h2><p>${t('timeDraftNote')}</p></div><div class="d-time-buttons">${[2,4,6,8].map(h=>`<button class="${state.profile.hours===h?'active':''}" data-action="plan-hours" data-hours="${h}" aria-pressed="${state.profile.hours===h}">${h}<small>${t('hours')}</small></button>`).join('')}</div>${button(t('makeMyPlan'),'build-plan','primary-button','arrow')}</section>`:`<div class="d-plan-status"><span>${esc(local(role.title))}<small>${t('paceSummary').replace('{n}',state.profile.hours)} · ~ ${role.weeks} ${t('weeks')}</small></span>${button(t('adjustPace'),'adjust-time','d-text-button','clock')}</div>${!state.pro?`<section class="d-starter-task"><span class="d-eyebrow">FREE / ${t('firstPractice')}</span><h2>${t(strategy.id==='income'?'weekApplications':'step1')}</h2><p>${t(strategy.id==='income'?'weekApplicationsDesc':'step1Desc')}</p><span class="d-starter-resource">${t('practice')} · ~ 4 ${t('hours')}</span><div class="d-starter-next"><span>${t('gapShort')}</span><strong>${role.missing.map(c.skillName).map(esc).join(' · ')||t('step3')}</strong></div></section>`:''}${executionPanel(c)}${state.pro?`<div class="d-plan-tools">${button(t('compare'),'compare','small-button','compare')}${button(t('export'),'export','small-button','download')}</div>`:''}${reflectionPanel(c)}`}<details class="d-evidence"><summary>${t('sourceDetails')} · O*NET / SDG ${role.sdg}</summary><p>${t('fitNote')}</p><p>${t('sdgExplain')}</p>${c.sourceLink(role.source,`O*NET · ${role.code}`)}</details></main>`}

export function compactPricing(c){const {t,state,button,icon}=c;return `<main class="d-page d-pricing-page"><div class="d-page-heading"><span class="d-eyebrow">FREE TO EXPLORE. ROOM TO GROW.</span><h1>${t('quietPricingTitle')}</h1><p>${t('quietPricingSub')}</p></div><section class="d-pricing-grid"><article><span class="d-eyebrow">REPATH FREE</span><h2>${t('quietFreeTitle')}</h2><strong class="d-price">RM 0</strong><p>${t('quietFreeDesc')}</p><ul>${t('quietFreeFeatures').map(x=>`<li>${icon('check')}${c.esc(x)}</li>`).join('')}</ul>${button(t('startFree'),'start-free','small-button','arrow')}</article><article class="d-featured-plan"><span class="d-eyebrow">REPATH PRO</span><h2>${t('quietProTitle')}</h2><strong class="d-price">RM 19<small>${t('month')}</small></strong><p>${t('quietProDesc')}</p><ul>${t('quietProFeatures').map(x=>`<li>${icon('check')}${c.esc(x)}</li>`).join('')}</ul>${button(t(state.pro?'viewFullPlan':'quietEnable'),'enable-pro','primary-button','arrow')}</article></section><p class="d-small-note">${t('priceNote')}</p></main>`}

export function compactAuth(c){const {t,state,button,esc,icon}=c;return `<main class="d-page d-auth-page"><div class="d-page-heading"><span class="d-eyebrow">REPATH / ${t('demo')}</span><h1>${t('quietLoginTitle')}</h1><p>${t('quietLoginSub')}</p></div><section class="d-auth-card"><div class="d-auth-tabs"><button data-action="auth-mode" data-mode="signin" class="${state.authMode==='signin'?'active':''}">${t('signIn')}</button><button data-action="auth-mode" data-mode="signup" class="${state.authMode==='signup'?'active':''}">${t('signUp')}</button></div><form id="account-form"><label class="field">${t('nickname')}<input name="nickname" maxlength="40" value="${esc(state.profile.name)}" required></label><button type="submit" class="primary-button">${t('quietLoginButton')}${arrow(c)}</button></form><p>${t('quietLoginNote')}</p><button class="d-text-button" data-action="show-sample">${t('seeExample')}${arrow(c)}</button></section></main>`}
